"""Persist a paired ablation report as evidence becomes available."""
import sys as _delivery_sys
from pathlib import Path as _DeliveryPath
_delivery_sys.dont_write_bytecode = True
_delivery_root = next(parent for parent in _DeliveryPath(__file__).resolve().parents if (parent / 'models/source_layout.py').is_file())
if str(_delivery_root) not in _delivery_sys.path:
    _delivery_sys.path.insert(0, str(_delivery_root))
from models.source_layout import experiment_directory
from models.model_catalog import resolve_artifact as _resolve_model_artifact, artifact_glob as _model_artifact_glob, temporary_settings as _temporary_model_settings
from pathlib import Path
import json, csv
HERE = experiment_directory(__file__)
ROOT = HERE.parents[1]

def duration(s):
    return f'{int(s // 3600)} h {int(s % 3600 // 60)} min {s % 60:.2f} s'

def main():
    evaluation = json.loads(_resolve_model_artifact(HERE / 'results/evaluation.json').read_text(encoding='utf-8'))
    names = {'full_M1': 'M1-H2-D2 completo', 'geometry_frozen_full_thresholds': 'Sólo geometría, umbrales del modelo completo', 'geometry_recalibrated_development': 'Sólo geometría, umbrales elegidos en desarrollo'}
    quality = []
    for key, value in evaluation['summary'].items():
        quality.append(f"| {names[key]} | {value['temporal_f1_macro_equal_fold_mean']:.6f} | {value['temporal_f1_line_equal_fold_mean']:.6f} | {value['temporal_f1_scrum_equal_fold_mean']:.6f} | {value['block_f1_macro_equal_fold_mean']:.6f} | {value['far_false_positives_per_hour_equal_fold_mean']:.3f} |")
    video_section = 'Pendiente de completar la inferencia desde el video.'
    if _resolve_model_artifact(HERE / 'results/completion.json').exists():
        check = json.loads(_resolve_model_artifact(HERE / 'results/completion.json').read_text(encoding='utf-8'))
        assert check['all_checks_pass'] and check['hashes_unchanged']
        result = json.loads(_resolve_model_artifact(HERE / 'results/result.json').read_text(encoding='utf-8'))
        timing = result['metadata']['timing']
        assert timing['counts']['ResNet_calls'] == timing['counts']['dual_BiGRU_calls'] == 0
        original = json.loads(_resolve_model_artifact(ROOT / 'data/top5_vf_sequential_20261012/results/M1-H2-D2_result.json').read_text(encoding='utf-8'))
        base = original['metadata']['timing']
        rows = []
        for key, r, t in [('YOLO_only', result, timing), ('M1_complete', original, base)]:
            rows.append({'model': key, 'inference_seconds': t['inference_seconds'], 'projection_80min_seconds': t['projection_80min_seconds'], 'events': len(r['detections']), 'scrum': sum((w['play_type'] == 'scrum' for w in r['detections'])), 'line': sum((w['play_type'] == 'line' for w in r['detections']))})
        (HERE / 'review_summary.json').write_text(json.dumps({'completed_models': 2, 'rows': rows}, indent=2), encoding='utf-8')
        table = '\n'.join((f"| {r['model']} | {duration(r['inference_seconds'])} | {duration(r['projection_80min_seconds'])} | {r['events']} ({r['scrum']} scrum / {r['line']} lineout) |" for r in rows))
        video_section = f"| Recorrido | Inferencia de 20 min 1.2 s | Proyección a 80 min | Eventos para revisar |\n| --- | ---: | ---: | ---: |\n{table}\n\nEl nuevo recorrido tardó {duration(timing['inference_seconds'])}; importación {timing['imports_seconds']:.3f} s, carga {timing['model_load_seconds']:.3f} s y calentamiento {timing['warmup_seconds']:.3f} s se registraron aparte. Se hicieron 30030 llamadas YOLO, 1195 ventanas y 7170 llamadas a los seis bosques, con cero llamadas a ResNet y al BiGRU dual. Se utilizó la misma decodificación, normalización espacial, ROI, muestreo a 25 FPS y submuestreo de 100 observaciones geométricas por ventana que en el M1 completo. Las filas de características vacías de una columna permiten reutilizar el iterador original; el clasificador las ignora y no contienen apariencia.\n\nLa extracción YOLO se volvió a ejecutar sobre VF_S01 completo: no se leyeron ni compartieron características persistidas del video. Las observaciones recién calculadas se conservan en memoria entre ventanas solapadas, como en el recorrido anterior. La proyección se obtiene multiplicando el tiempo por 4800/1201.2. La comparación de tiempos corresponde a dos ejecuciones distintas, no a una prueba simultánea con condiciones de CPU idénticas. Los umbrales del video de sólo geometría son las medianas de los seleccionados en desarrollo: {evaluation['video_thresholds_median_development_folds']}. El M1 completo de referencia usó scrum 0.75 y lineout 0.80; sus conteos de eventos no son una comparación de exactitud con una política idéntica.\n\n`results/result.json`, `events.csv`, `windows.csv`, `timing.json`, `startup.json`, `adapter_validation.json` y `completion.json` conservan las predicciones, tiempos y verificaciones. El resultado completo se puede revisar junto con M1 en http://127.0.0.1:8768/."
    text = f"# Ablación de M1-H2-D2: sólo YOLO y geometría, sin apariencia RGB\n\nSe reutilizan los seis bosques de geometría de M1-H2-D2 ya entrenados: YOLO produce cajas, posiciones, posturas y máscaras; nueve resúmenes por cada una de las 61 variables forman las 549 características del bosque. No se carga ni ejecuta ResNet-50 ni el BiGRU que fusiona RGB y pose. No se reentrena ningún componente ni se sustituye una entrada RGB por ceros dentro de una red multimodal entrenada.\n\n## Calidad sobre etiquetas disponibles\n\nComparación pareada sobre los seis tests externos por fold del Panel V: {evaluation['total_heldout_blocks']} bloques, cada uno predicho por el bosque que no se entrenó con ese video. Se respeta la partición original de entrenamiento/desarrollo/test. Se comprueba que las probabilidades de los bosques sobre todo el test reproducen las columnas `p_geometry_*` guardadas, con tolerancia absoluta 1e-12, y que las métricas del M1 completo reproducen sus métricas publicadas. No se promedian seis bosques entrenados con los videos de test para calcular estas métricas.\n\n| Variante | F1 temporal medio | F1 temporal lineout | F1 temporal scrum | F1 macro por bloque | Falsos positivos lejanos/h |\n| --- | ---: | ---: | ---: | ---: | ---: |\n{chr(10).join(quality)}\n\nLa rama recalibrada conserva un F1 temporal medio de 0.526086 frente a 0.600817 del modelo completo. Lineout queda en 0.583084 frente a 0.566995, mientras scrum cae a 0.469087 frente a 0.634639. Los falsos positivos lejanos aumentan de 10.954 a 13.992 por hora en promedio por fold. Hay capacidad de detectar jugadas usando sólo las salidas geométricas de YOLO, pero esta variante pierde calidad global, principalmente en scrum. La ligera mejora media de lineout no se acompaña aquí de una prueba de significación estadística.\n\nSon medias con el mismo peso por fold, no porcentajes de detecciones correctas en VF_S01. El F1 temporal pondera la distancia entre eventos, con la función original del protocolo. Se presentan dos políticas para la rama aislada: conservar los umbrales del modelo completo, y elegir nuevos umbrales exclusivamente en el video de desarrollo de cada fold. La búsqueda usa la misma cuadrícula y el mismo criterio temporal que el protocolo original; nunca el test. Así se distingue la ablación con umbrales fijos del potencial de la rama recalibrada. Las matrices de confusión, precisión, recall y F1 por clase, métricas temporales y umbrales de cada fold están en `results/PV*_metrics.json`; `heldout_predictions.csv` permite auditar todos los bloques.\n\nLa evaluación usa sólo vectores geométricos cacheados del corpus para evitar repetir la extracción YOLO del dataset; no se usan características RGB para clasificar ni se contabiliza esta evaluación como inferencia completa del video. Las métricas de calidad presentadas aquí corresponden al Panel V y no se trasladan automáticamente al ensemble del video VF_S01.\n\nCorrección de disponibilidad de anotaciones: al preparar la banda «Real» incorporada en una revisión posterior se localizó la sesión manual completa `20260830_112524_0b5e58` de VF_S01. Antes se había indicado por error que no había etiquetas completas en este experimento. Su manifiesto, registro de revisión y sesión concuerdan en 172 bloques, sin huecos, desde 0 hasta 1201.2 s: 134 `other`, 18 `line` y 20 `scrum`. Al unir bloques contiguos de la misma clase hay 8 intervalos de lineout y 5 de scrum. Esas etiquetas se usan para la banda real de las imágenes; esta actualización no calcula nuevas métricas de exactitud de los ensembles sobre VF_S01 ni altera sus predicciones o umbrales. Los límites reales tienen la resolución de los bloques anotados de 7 s, no precisión de cuadro.\n\n## Video final y tiempos\n\n{video_section}\n\n## Alcance de la conclusión\n\nEsta prueba mide la rama de geometría existente, no todas las posibles arquitecturas que se podrían entrenar sólo con pose. Quitar RGB también elimina el BiGRU dual, porque ese clasificador requiere RGB en su diseño. Por lo tanto, una caída de calidad aquí no prueba que cualquier modelo entrenado exclusivamente con YOLO vaya a rendir igual. El recorrido conserva el estimador YOLO y la geometría de M1; YOLO sigue leyendo imágenes para detectar personas, aunque el clasificador de jugadas usa únicamente sus salidas geométricas.\n\nEl audit hook limita las escrituras Python a esta carpeta; los temporales y configuración de bibliotecas se redirigen a `runtime`. Los hashes del video, YOLO, bosques y fuentes originales se verifican antes y después. Se comprueba por comparación exacta que la fórmula de las 549 características coincide con la del M1 completo en entradas sintéticas de distintas longitudes. `evaluation.json` conserva la auditoría de los folds y `completion.json` la de la ejecución completa. Todos los resultados nuevos se guardan exclusivamente aquí.\n\nEl visor se puede reabrir con `review.ps1`; `review_preview.png` muestra ambas tablas. Se comprobó que la marca de scrum 03:16 lleva el video a 03:13 y que cambiar al M1 completo conserva ese momento, con sus propias probabilidades y ocho eventos. `final_validation.json` registra la auditoría final de los artefactos y del servicio local.\n\n`figures/comparacion_real_inferencias_20min.png` y su detalle de 6 minutos comparan Real, RGB + YOLO y sólo YOLO con el estilo de las slides. Sus versiones SVG y `image_with_real_evidence.json` conservan los intervalos y hashes de las fuentes manuales verificadas. Las imágenes generadas se guardan por separado.\n"
    (HERE / 'README.md').write_text(text, encoding='utf-8')
    print(json.dumps({'evaluation_complete': True, 'video_complete': _resolve_model_artifact(HERE / 'results/completion.json').exists(), 'summary': evaluation['summary']}))
if __name__ == '__main__':
    main()
